# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PAST PERFECT SIMPLE (had + V3) VE ZAMAN BAĞLAÇLARI</text>\n  <line x1="60" y1="75" x2="640" y2="75" stroke="#334155" stroke-width="3"/>\n  <polygon points="640,75 628,69 628,81" fill="#334155"/>\n  <circle cx="170" cy="75" r="9" fill="#2563eb"/>\n  <circle cx="390" cy="75" r="9" fill="#dc2626"/>\n  <circle cx="580" cy="75" r="8" fill="#16a34a"/>\n  <text x="170" y="55" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1st Action (Earlier Past)</text>\n  <text x="170" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">PAST PERFECT (had + V3)</text>\n  <text x="390" y="55" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">2nd Action (Later Past)</text>\n  <text x="390" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">SIMPLE PAST (V2)</text>\n  <text x="580" y="55" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">NOW</text>\n  <text x="580" y="98" text-anchor="middle" font-size="10" fill="#15803d">Present</text>\n  <rect x="25" y="118" width="315" height="104" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="182" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">AFTER / AS SOON AS Kalıbı</text>\n  <text x="182" y="162" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">After + [had + V3] , [Simple Past V2]</text>\n  <text x="182" y="182" text-anchor="middle" font-size="9.5" fill="#334155">• After he had graduated, he started work.</text>\n  <text x="182" y="200" text-anchor="middle" font-size="9.5" fill="#334155">• As soon as she had finished, she called me.</text>\n  <rect x="360" y="118" width="315" height="104" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="517" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">BEFORE / BY THE TIME Kalıbı</text>\n  <text x="517" y="162" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">By the time + [Simple Past V2] , [had + V3]</text>\n  <text x="517" y="182" text-anchor="middle" font-size="9.5" fill="#334155">• Before he moved to Rome, he had learned Italian.</text>\n  <text x="517" y="200" text-anchor="middle" font-size="9.5" fill="#334155">• By the time the train arrived, we had bought tickets.</text>\n</svg>', '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PAST PERFECT SIMPLE vs. PAST PERFECT CONTINUOUS</text>\n  <rect x="20" y="44" width="320" height="184" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">PAST PERFECT SIMPLE (had + V3)</text>\n  <rect x="34" y="78" width="292" height="136" rx="6" fill="#ffffff" stroke="#818cf8"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">Odak: Tamamlanma, Sonuç ve Miktar</text>\n  <text x="180" y="118" text-anchor="middle" font-size="9.5" fill="#334155">• Eylem geçmişteki referans anından önce bitmiştir.</text>\n  <text x="180" y="136" text-anchor="middle" font-size="9.5" fill="#334155">• \'Kaç kez / ne kadar?\' (How many/much) yanıtlar.</text>\n  <text x="180" y="154" text-anchor="middle" font-size="9.5" fill="#334155">• Stative verbs (know, be, own) ile zorunludur.</text>\n  <text x="180" y="176" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e1b4b">Örnek: She had written three books by 2015.</text>\n  <text x="180" y="196" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e1b4b">Örnek: We had known him for years.</text>\n  <rect x="360" y="44" width="320" height="184" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">PAST PERFECT CONTINUOUS (had been + V-ing)</text>\n  <rect x="374" y="78" width="292" height="136" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Odak: Süreç, Devamlılık ve Süre (Duration)</text>\n  <text x="520" y="118" text-anchor="middle" font-size="9.5" fill="#334155">• Eylem geçmişteki referans anına dek sürmüştür.</text>\n  <text x="520" y="136" text-anchor="middle" font-size="9.5" fill="#334155">• \'Ne kadar süredir?\' (How long / for / since) vurgular.</text>\n  <text x="520" y="154" text-anchor="middle" font-size="9.5" fill="#334155">• Geçmişteki görünür sonucun (yorgunluk vb.) nedenidir.</text>\n  <text x="520" y="176" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#14532d">Örnek: She had been working in the lab for 6 hours</text>\n  <text x="520" y="196" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#14532d">when she made the breakthrough discovery.</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BİYOGRAFİK ANLATI (BIOGRAPHICAL NARRATIVE) AKIŞ ŞEMASI</text>\n  <rect x="20" y="50" width="150" height="150" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="95" y="72" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. EARLY LIFE</text>\n  <text x="95" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• was born in / grew up</text>\n  <text x="95" y="112" text-anchor="middle" font-size="9.5" fill="#334155">• attended school</text>\n  <text x="95" y="130" text-anchor="middle" font-size="9.5" fill="#334155">• graduated from</text>\n  <text x="95" y="148" text-anchor="middle" font-size="9.5" fill="#334155">• won a scholarship</text>\n  <text x="95" y="174" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1d4ed8">Doğum ve Eğitim</text>\n  <rect x="190" y="50" width="150" height="150" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="265" y="72" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">2. STRUGGLES</text>\n  <text x="265" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• faced difficulties</text>\n  <text x="265" y="112" text-anchor="middle" font-size="9.5" fill="#334155">• had been working</text>\n  <text x="265" y="130" text-anchor="middle" font-size="9.5" fill="#334155">• perseverance</text>\n  <text x="265" y="148" text-anchor="middle" font-size="9.5" fill="#334155">• overcame obstacles</text>\n  <text x="265" y="174" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">Çaba ve Azim</text>\n  <rect x="360" y="50" width="150" height="150" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="435" y="72" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">3. TURNING POINT</text>\n  <text x="435" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• milestone / turning point</text>\n  <text x="435" y="112" text-anchor="middle" font-size="9.5" fill="#334155">• made a breakthrough</text>\n  <text x="435" y="130" text-anchor="middle" font-size="9.5" fill="#334155">• patented an invention</text>\n  <text x="435" y="148" text-anchor="middle" font-size="9.5" fill="#334155">• published a masterpiece</text>\n  <text x="435" y="174" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#7e22ce">Dönüm Noktası</text>\n  <rect x="530" y="50" width="150" height="150" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="605" y="72" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">4. LEGACY</text>\n  <text x="605" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• received Nobel Prize</text>\n  <text x="605" y="112" text-anchor="middle" font-size="9.5" fill="#334155">• pioneer in science</text>\n  <text x="605" y="130" text-anchor="middle" font-size="9.5" fill="#334155">• contributed to humanity</text>\n  <text x="605" y="148" text-anchor="middle" font-size="9.5" fill="#334155">• passed away / remembered</text>\n  <text x="605" y="174" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">Ödül ve Miras</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
